steps.run:
$path = "bitwarden_license\bitwarden-access-connector\bundle\templates\bwac-launcher.ps1"
$errors = $null
$tokens = $null
[void] [System.Management.Automation.Language.Parser]::ParseFile(
    (Resolve-Path $path).Path, [ref] $tokens, [ref] $errors)
if ($errors) {
    $errors | ForEach-Object {
        Write-Host "::error file=$path,line=$($_.Extent.StartLineNumber)::$($_.Message)"
    }
    exit 1
}
Write-Host "$path parses clean"

with.script:
await github.rest.actions.createWorkflowDispatch({
  owner: 'bitwarden',
  repo: 'sdk-internal',
  workflow_id: 'release-swift.yml',
  ref: 'main',
  inputs: {
    'build-run-id': '${{ github.run_id }}',
    'build-run-number': '${{ github.run_number }}',
    'sdk-swift-branch-name': 'unstable',
    'update-ios-repo': 'true',
  }
})
